import math

state = {
    'mode': 'pull_forward',
    'pull_fwd_start_t': None,
}

def control(obs):
    t = obs.get('t', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    v_mps = obs.get('motion', {}).get('v_mps', 0.0)

    screen_gaze = obs.get('rig', {}).get('screen_gaze_deg', -23.0)
    look_target = screen_gaze if screen_gaze is not None else -23.0

    if hold_s > 0:
        return {"steer_deg": 0.0, "speed_mps": 0.0, "look_deg": look_target}

    # In pull_forward mode, pull forward until we have actually moved for at least 3 seconds
    if state['mode'] == 'pull_forward':
        if state['pull_fwd_start_t'] is None:
            # Only start timer once vehicle is actually rolling forward
            if v_mps > 0.1:
                state['pull_fwd_start_t'] = t

        if state['pull_fwd_start_t'] is None or (t - state['pull_fwd_start_t']) < 3.0:
            # Pull forward with slight steer right or left to clear rail
            return {"steer_deg": 5.0, "speed_mps": 1.0, "look_deg": look_target}
        else:
            state['mode'] = 'reverse'

    # Reversing mode
    speed = -0.7

    # Camera views
    views = obs.get('views', {})
    cam = views.get('camera')
    trailer_axis = 180.0 - hitch

    left_wall_dists = []
    right_wall_dists = []
    target_bearing_in_trailer = None

    if cam and 'walls' in cam:
        cam_axis = cam.get('axis_deg', trailer_axis)
        for b, d in cam['walls']:
            rel_angle = (b - cam_axis)
            rel_angle = (rel_angle + 180.0) % 360.0 - 180.0
            lat_d = d * math.sin(math.radians(rel_angle))
            long_d = d * math.cos(math.radians(rel_angle))
            if long_d > 0.1:
                if lat_d > 0.1:
                    left_wall_dists.append(lat_d)
                elif lat_d < -0.1:
                    right_wall_dists.append(-lat_d)

    if cam and 'target_corners' in cam and cam['target_corners']:
        corners = cam['target_corners']
        cam_axis = cam.get('axis_deg', trailer_axis)
        mean_rel = sum((c[0] - cam_axis + 180.0) % 360.0 - 180.0 for c in corners) / len(corners)
        target_bearing_in_trailer = mean_rel
    elif obs.get('target', {}).get('in_sight'):
        tb = obs['target']['bearing_deg']
        err_v = (tb - 180.0) if tb > 0 else (tb + 180.0)
        target_bearing_in_trailer = err_v + hitch

    target_hitch = 0.0
    if target_bearing_in_trailer is not None:
        # Proportional response to guide trailer toward target
        target_hitch = max(-25.0, min(25.0, target_bearing_in_trailer * 0.7))

    # Wall safety margin (trailer width 1.7m -> half-width 0.85m)
    if left_wall_dists:
        min_left = min(left_wall_dists)
        if min_left < 1.1:
            # Too close to left rail -> drive hitch negative to turn trailer right
            target_hitch -= (1.1 - min_left) * 15.0
