            target_hitch += (1.1 - min_right) * 15.0

    target_hitch = max(-25.0, min(25.0, target_hitch))

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.2
    steer = max(-34.0, min(34.0, steer))

