import math

look_idx = 0
last_head_switch_t = 0.0

def control(obs):
    global look_idx, last_head_switch_t
    t = obs['t']
    hitch = obs['hitch_deg']
    speed = obs['speed']['default_rev']
    v_target = -min(speed, 1.0)

    # Alternating glance between left and right mirrors (+64 deg / -64 deg)
    if t - last_head_switch_t > 2.5:
        look_idx = 1 - look_idx
        last_head_switch_t = t
    look_target = 64.0 if look_idx == 0 else -64.0

    left_clearance = 999.0
    right_clearance = 999.0

    for view_name, view in obs.get('views', {}).items():
        if not view:
            continue
        ox, oy = view['origin']
        for b_deg, d in view.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            if -8.0 <= px <= 2.0:
                if py > 0:
                    left_clearance = min(left_clearance, py)
                else:
                    right_clearance = min(right_clearance, -py)

    target_hitch = 0.0
    if left_clearance < 900.0 and right_clearance < 900.0:
        err_y = left_clearance - right_clearance
        target_hitch = max(-15.0, min(15.0, err_y * 10.0))
    elif left_clearance < 900.0:
        if left_clearance < 1.8:
            target_hitch = -10.0
    elif right_clearance < 900.0:
        if right_clearance < 1.8:
            target_hitch = 10.0

    target_info = obs.get('target', {})
    if target_info.get('in_sight'):
        tb = target_info.get('bearing_deg', 0.0)
        if tb > 0:
            dev = 180.0 - tb
        else:
            dev = -180.0 - tb
        target_hitch = max(-20.0, min(20.0, dev * 0.8))

    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.2
    steer = max(-40.0, min(40.0, steer))

    return {'steer_deg': steer, 'speed_mps': v_target, 'look_deg': look_target}

