import math

# Controller to pull forward away from the right rail and reverse smoothly through the S-bend
mode = 'PULL_FORWARD'
fwd_dist_start = None

def control(obs):
    global mode, fwd_dist_start
    t = obs['t']
    hitch = obs['hitch_deg']
    hold = obs['motion']['hold_s']
    cov = obs['progress']['covered']

    # Right mirror shows the rail where we clipped
    look_target = -64.0

    if mode == 'PULL_FORWARD':
        if hold > 0:
            return {'steer_deg': -10.0, 'speed_mps': 1.0, 'look_deg': 0.0}
        if fwd_dist_start is None:
            fwd_dist_start = cov

        # Pull forward 4.5m to give ample room to align trailer
        if cov > fwd_dist_start - 4.5:
            return {'steer_deg': -10.0, 'speed_mps': 1.0, 'look_deg': 0.0}
        else:
            mode = 'REVERSE'

    # Reversing through the S-bend:
    min_right = 999.0
    min_left = 999.0
    for view_name, view in obs.get('views', {}).items():
        if not view:
            continue
        ox, oy = view['origin']
        for b_deg, d in view.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            if -7.5 <= px <= 0.5:
                if py < 0:
                    min_right = min(min_right, -py)
                else:
                    min_left = min(min_left, py)

    # Positive hitch swings trailer rear left (away from right rail)
    target_hitch = 8.0
    if min_right < 1.6:
        target_hitch = 14.0
    elif min_right < 1.9:
        target_hitch = 10.0
    elif min_left < 1.6:
        target_hitch = -6.0

    target_info = obs.get('target', {})
    if target_info.get('in_sight'):
        tb = target_info.get('bearing_deg', 0.0)
        dev = (180.0 - tb) if tb > 0 else (-180.0 - tb)
        target_hitch = max(-20.0, min(20.0, dev * 0.8))

    # Closed loop on hitch:
    # hitch_err = hitch - target_hitch
    # If hitch < target_hitch, steer < 0 (steer right) to drive hitch up.
    hitch_err = hitch - target_hitch
    steer = hitch_err * 2.5
    steer = max(-45.0, min(45.0, steer))

    return {'steer_deg': steer, 'speed_mps': -0.6, 'look_deg': look_target}

