import math

phase = 'UNPIN_FORWARD'
fwd_start_t = None

def control(obs):
    global phase, fwd_start_t
    t = obs['t']
    hitch = obs['hitch_deg']
    hold = obs['motion']['hold_s']

    if hold > 0:
        return {'steer_deg': 10.0, 'speed_mps': 0.0, 'look_deg': 0.0}

    if phase == 'UNPIN_FORWARD':
        if fwd_start_t is None:
            fwd_start_t = t
        if abs(hitch) > 8.0 and (t - fwd_start_t < 4.0):
            return {'steer_deg': 10.0, 'speed_mps': 0.6, 'look_deg': 0.0}
        else:
            phase = 'REVERSE'

    look_target = -64.0 if int(t / 2.5) % 2 == 0 else 64.0

    left_dist = 999.0
    right_dist = 999.0
    for view_name, view in obs.get('views', {}).items():
        if not view:
            continue
        ox, oy = view['origin']
        for b_deg, d in view.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            if -7.0 <= px <= 1.5:
                if py > 0:
                    left_dist = min(left_dist, py)
                else:
                    right_dist = min(right_dist, -py)

    target_hitch = 0.0
    if left_dist < 50.0 and right_dist < 50.0:
        diff = left_dist - right_dist
        target_hitch = max(-8.0, min(8.0, diff * 4.0))
    elif right_dist < 50.0:
        target_hitch = max(0.0, min(8.0, (1.8 - right_dist) * 5.0))
    elif left_dist < 50.0:
        target_hitch = max(-8.0, min(0.0, -(1.8 - left_dist) * 5.0))

    hitch_err = hitch - target_hitch
    steer = max(-25.0, min(25.0, hitch_err * 1.5))

    return {'steer_deg': steer, 'speed_mps': -0.4, 'look_deg': look_target}

