import math

state = {
    'mode': 'pull_forward',
    'fwd_dist': 0.0,
    'last_covered': None,
}

def control(obs):
    status = obs.get('status', '')
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    steer = obs.get('steer_deg', 0.0)
    covered = obs.get('progress', {}).get('covered', 0.0)
    dt = obs.get('dt', 0.1)

    look_target = 165.0

    if hold_s > 0.0:
        return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_target}

    # In pull-forward mode: pull forward 3.5m towards the right side to gain ample space from left rail
    if state['mode'] == 'pull_forward':
        if state['last_covered'] is not None:
            diff = state['last_covered'] - covered
            if diff > 0:
                state['fwd_dist'] += diff
        state['last_covered'] = covered

        if state['fwd_dist'] < 3.5:
            # Steer right (negative) to drive front/rear of vehicle away from left rail
            # Trailer will follow and straighten
            steer_target = -18.0 if state['fwd_dist'] < 2.0 else 0.0
            return {'steer_deg': steer_target, 'speed_mps': 0.5, 'look_deg': look_target}
        else:
            state['mode'] = 'reverse'
            state['last_covered'] = None

    # Reversing mode: slow and cautious
    v_target = -0.3

    # Calculate wall positions
    left_ys = []
    right_ys = []
    for vname, vdata in obs.get('views', {}).items():
        orig = vdata.get('origin', [0, 0])
        ox, oy = orig[0], orig[1]
        for b_deg, dist in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + dist * math.cos(rad)
            py = oy + dist * math.sin(rad)
            if -2.5 <= px <= 1.5:
                if py > 0:
                    left_ys.append(py)
                else:
                    right_ys.append(-py)

    target_hitch = 0.0
    # Notice: vehicle half width is 0.525m. Left wall was at ~0.6-0.75m from center.
    # Right wall points were at ~3.0 - 3.5m! The alley is very wide or offset to the right!
    if left_ys:
        min_l = min(left_ys)
        # If left clearance is less than 1.2m, steer to move right away from left wall
        # Moving right in reverse requires positive trailer angle (hitch < 0 => trailer rear swung right!)
        # Hitch < 0 means trailer points right relative to vehicle.
        if min_l < 1.1:
            target_hitch = -8.0
        elif min_l > 1.4 and right_ys and min(right_ys) < 1.1:
            target_hitch = 6.0
        else:
            target_hitch = 0.0

    # Check target bay corners if seen
    bay_corners = []
    for vname, vdata in obs.get('views', {}).items():
        for b_deg, dist in vdata.get('target_corners', []):
            bay_corners.append((b_deg, dist))
    if bay_corners:
        # Target corner detected, guide trailer towards bay center
        avg_b = sum(c[0] for c in bay_corners) / len(bay_corners)
        rel = avg_b - 180.0 if avg_b > 0 else avg_b + 180.0
        target_hitch = max(-10.0, min(10.0, -rel * 0.5))

    # PD control on hitch angle
    # When reversing: steer > 0 drives hitch down (towards negative)
    # hitch_err = hitch - target_hitch
    hitch_err = hitch - target_hitch
    steer_cmd = hitch_err * 2.2
    steer_cmd = max(-35.0, min(35.0, steer_cmd))

    return {'steer_deg': steer_cmd, 'speed_mps': v_target, 'look_deg': look_target}

