    hold_s = obs.get('motion', {}).get('hold_s', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    steer = obs.get('steer_deg', 0.0)
    look_target = -140.0

    if hold_s > 0.0:
        return {'steer_deg': -25.0, 'speed_mps': 0.0, 'look_deg': look_target}

    if state['mode'] == 'pull_forward':
        state['steps_fwd'] += 1
        if state['steps_fwd'] < 40:
            return {'steer_deg': -25.0, 'speed_mps': 0.5, 'look_deg': look_target}
        elif state['steps_fwd'] < 55:
            return {'steer_deg': 5.0, 'speed_mps': 0.5, 'look_deg': look_target}
        else:
            state['mode'] = 'reverse'

    v_target = -0.22
    t_info = obs.get('target', {})
    bay_bearing = t_info.get('bearing_deg', -140.0) if t_info.get('in_sight') else -140.0

    rel_rear = bay_bearing + 180.0 if bay_bearing < 0 else bay_bearing - 180.0
    target_hitch = -rel_rear * 0.4
    target_hitch = max(-20.0, min(5.0, target_hitch))

    min_l = 99.0
    for vname, vdata in obs.get('views', {}).items():
        ox, oy = vdata.get('origin', [0, 0])
        for b_deg, dist in vdata.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + dist * math.cos(rad)
            py = oy + dist * math.sin(rad)
            if -2.2 <= px <= 1.2 and py > 0:
                min_l = min(min_l, py)

    if min_l < 1.2:
        target_hitch = min(target_hitch, -12.0)

    hitch_err = hitch - target_hitch
    steer_cmd = hitch_err * 2.2
    steer_cmd = max(-35.0, min(35.0, steer_cmd))

    return {'steer_deg': steer_cmd, 'speed_mps': v_target, 'look_deg': look_target}
